INSERT INTO Mechanics.ServiceCatalog (Id, Name, Description, BasePrice, AverageTime, Status, CreationDate)
VALUES  (N'f42c1cbe-7c2e-4ad1-a275-11d20d9648e6', N'TROCA DE ÓLEO DE CÂMBIO MANUAL', N'Drenagem completa do óleo do câmbio manual, limpeza do tampão magnético, reabastecimento com óleo especificado pelo fabricante.', 200.00, 50, 0, N'2025-11-12 23:47:01.1850957'),
        (N'58d9c879-c1bb-433a-b9b8-2e802778d2bf', N'SUBSTITUIÇÃO DE DISCOS DE FREIO', N'Troca do par de discos de freio (dianteiros ou traseiros), verificação dos calibres, limpeza e lubrificação dos componentes móveis.', 380.00, 90, 0, N'2025-11-12 23:47:01.1307461'),
        (N'c1e56ae7-247f-4739-8c15-499c54966ed7', N'TROCA DE ÓLEO E FILTRO', N'Troca completa de óleo lubrificante do motor, substituição do filtro de óleo e verificação dos níveis de fluidos. Inclui óleo sintético ou semissintético conforme especificação do veículo.', 180.00, 45, 0, N'2025-11-12 23:47:00.7904460'),
        (N'1838066d-780b-4849-bb05-55d2abe3c46d', N'REGULAGEM DE MOTOR E INJEÇÃO ELETRÔNICA', N'Ajuste de marcha lenta, ponto de ignição, mistura ar/combustível, limpeza do corpo de borboleta e reset de adaptativas.', 280.00, 75, 0, N'2025-11-12 23:47:01.1600186'),
        (N'b623a04a-ae90-4b7d-b6f8-5ade43d889d9', N'TROCA DE EMBREAGEM COMPLETA', N'Substituição do kit de embreagem (platô, disco e rolamento), retífica do volante se necessário, verificação do cabo ou atuador hidráulico.', 1200.00, 360, 0, N'2025-11-12 23:47:01.0417355'),
        (N'36e9df29-015d-4187-a87d-70c8ec121d30', N'INSTALAÇÃO DE SISTEMA DE SOM', N'Instalação profissional de rádio, alto-falantes, amplificador ou subwoofer. Inclui passagem de cabos, fixações e testes completos.', 350.00, 180, 0, N'2025-11-12 23:47:01.2100872'),
        (N'a5d68559-23e2-4131-9a29-7d98a3f640dc', N'HIGIENIZAÇÃO COMPLETA DO AR CONDICIONADO', N'Limpeza profunda do sistema de ar condicionado com produtos bactericidas e antifúngicos, troca do filtro de cabine, eliminação de odores.', 180.00, 60, 0, N'2025-11-12 23:47:01.3104609'),
        (N'f41a209f-1332-4913-a186-81c234d2ab9d', N'TROCA DE BOMBA DE COMBUSTÍVEL', N'Substituição da bomba de combustível elétrica, limpeza do tanque, troca do pré-filtro, verificação de pressão e vazão do sistema.', 550.00, 150, 0, N'2025-11-12 23:47:01.2562313'),
        (N'8985abd7-7c88-41c7-8c58-8a3ac1017401', N'SUBSTITUIÇÃO DE PASTILHAS DE FREIO DIANTEIRAS', N'Troca das pastilhas de freio dianteiras, limpeza dos calibres, lubrificação de pinos e guias, verificação do nível do fluido de freio.', 280.00, 75, 0, N'2025-11-12 23:47:00.9660578'),
        (N'd9e5db52-9c1a-4197-b242-8c93b4aa860c', N'TROCA DE VELAS DE IGNIÇÃO', N'Substituição das velas de ignição, limpeza do compartimento, verificação dos cabos de vela e bobinas, regulagem da folga das velas.', 180.00, 45, 0, N'2025-11-12 23:47:01.1053480'),
        (N'57f4809b-2fbe-4778-a13d-9210007e5a77', N'REVISÃO COMPLETA DE FREIOS', N'Inspeção detalhada do sistema de freios, verificação de pastilhas, discos, lonas, tambores, cilindros e fluido de freio. Inclui regulagem e limpeza dos componentes.', 250.00, 90, 0, N'2025-11-12 23:47:00.8363905'),
        (N'9d542901-4573-40e0-86d1-9b5d4a4c4a78', N'REVISÃO DE SUSPENSÃO COMPLETA', N'Inspeção e diagnóstico completo da suspensão dianteira e traseira: amortecedores, molas, bandejas, pivôs, bieletas, buchas e terminais de direção.', 180.00, 60, 0, N'2025-11-12 23:47:01.2311175'),
        (N'053cc64b-a4e7-4eeb-9991-9ef308e7ea45', N'ALINHAMENTO E BALANCEAMENTO', N'Alinhamento computadorizado das rodas dianteiras e traseiras, balanceamento das quatro rodas com equipamento digital de alta precisão.', 120.00, 60, 0, N'2025-11-12 23:47:00.8658592'),
        (N'87950c9e-c0e4-4ee9-89c2-b1c297ed4b44', N'TROCA DE AMORTECEDORES DIANTEIROS', N'Substituição do par de amortecedores dianteiros, incluindo coxim, rolamento e batente. Verificação da suspensão e geometria.', 450.00, 120, 0, N'2025-11-12 23:47:00.9913486'),
        (N'21fad127-7ffc-4918-95ba-d4ec44a1b34a', N'TROCA DE CORREIA DENTADA COM KIT COMPLETO', N'Substituição da correia dentada, tensor automático, tensor fixo e bomba d''água. Inclui regulagem do ponto do motor e verificação de folgas.', 850.00, 240, 0, N'2025-11-12 23:47:00.8911013'),
        (N'108ef686-1ae1-4a66-b728-e3fd2f68dd74', N'TROCA DE BATERIA', N'Remoção da bateria antiga, limpeza dos terminais, instalação e fixação da bateria nova, teste do sistema de carga e verificação do alternador.', 80.00, 30, 0, N'2025-11-12 23:47:00.9451679'),
        (N'76c7e519-b229-4da6-8c92-f03b88ce7b98', N'POLIMENTO E CRISTALIZAÇÃO DE PINTURA', N'Polimento técnico em três etapas para remoção de riscos e oxidação, cristalização com cera de carnaúba, proteção UV.', 450.00, 240, 0, N'2025-11-12 23:47:01.2854125'),
        (N'725532cd-ec38-4611-88a2-f12862bcc901', N'DIAGNÓSTICO ELETRÔNICO COMPUTADORIZADO', N'Escaneamento completo dos sistemas eletrônicos do veículo com scanner automotivo profissional. Leitura e interpretação de códigos de falha, análise de sensores e atuadores.', 150.00, 30, 0, N'2025-11-12 23:47:00.9203580'),
        (N'6a7558f4-06a2-4110-a630-f541bff1abaf', N'LIMPEZA DE BICOS INJETORES', N'Limpeza profunda dos bicos injetores com equipamento de ultrassom, teste de vazão e pulverização, limpeza do corpo de borboleta.', 320.00, 90, 0, N'2025-11-12 23:47:01.0204470'),
        (N'a576bc4c-3ffd-440b-a099-fbf77bea4cc9', N'REVISÃO DO SISTEMA DE ARREFECIMENTO', N'Troca de fluido do radiador, teste de pressão do sistema, verificação de mangueiras, abraçadeiras, bomba d''água e válvula termostática.', 220.00, 60, 0, N'2025-11-12 23:47:01.0754671');

